// JAH demo program — Bell-state simulator (mini Qiskit-style)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function bell(){ var s=[1,0,0,0];
// H on q0
  var h=[[Math.SQRT1_2,Math.SQRT1_2],[Math.SQRT1_2,-Math.SQRT1_2]];
  var n=[0,0,0,0]; for(var i=0;i<4;i++){ var b=(i>>1)&1; for(var nb=0;nb<2;nb++){ var j=(i&1)|(nb<<1); n[j]+=h[b][nb]*s[i]; } }
  s=n; n=[0,0,0,0]; for(var k=0;k<4;k++){ var c=(k>>1)&1; var j2=c?(k^1):k; n[j2]+=s[k]; }
  return n.map(function(a){return Math.round(a*a*100)/100;}); }
var probs=bell();
check("P(|00>)=0.5", probs[0], 0.5);
check("P(|11>)=0.5", probs[3], 0.5);
check("P(|01>)=P(|10>)=0", probs[1]+probs[2], 0);
check("probabilities sum to 1", probs.reduce(function(a,b){return a+b;},0), 1);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

// JAH demo program — Grid-connectivity check
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function neighbors(q, rows, cols){ var r=Math.floor(q/cols), c=q%cols, n=[];
  if(r>0)n.push(q-cols); if(r<rows-1)n.push(q+cols); if(c>0)n.push(q-1); if(c<cols-1)n.push(q+1); return n; }
check("qubit 0 on 3x3 has 2 neighbors", neighbors(0,3,3).length, 2);
check("center qubit has 4", neighbors(4,3,3).length, 4);
check("corner qubits listed", neighbors(0,3,3).join(','), "3,1");
