// JAH demo program — Parameter-shift gradient (PennyLane's core trick)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function f(th){ return Math.cos(th); } // Pauli-Z expectation under Rx(th)
function grad(th){ return (f(th+Math.PI/2)-f(th-Math.PI/2))/2; } // parameter-shift rule
check("gradient of cos at \u03c0/4 \u2248 -0.707", Math.round(grad(Math.PI/4)*1000)/1000, -0.707);
check("gradient at \u03b8=0 \u2248 0", Math.abs(grad(0))<0.01, true);
