// JAH demo program — Gate-cancellation pass demo
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function cancel(gates){ var out=[]; gates.forEach(function(g){
  var top=out[out.length-1];
  if(top&&top[0]===g[0]&&top[1]===g[1]&&(g[0]==='X'||g[0]==='H')) out.pop(); else out.push(g); }); return out; }
check("X X cancels", cancel([['X',0],['X',0]]).length, 0);
check("H X H survives", cancel([['H',0],['X',0],['H',0]]).length, 3);
check("CNOT never cancels here", cancel([['CX',0],['CX',0]]).length, 2);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

// JAH demo program — QUBO energy demo
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function qubo(x,Q){ var e=0; for(var i=0;i<x.length;i++)for(var j=0;j<x.length;j++)e+=Q[i][j]*x[i]*x[j]; return e; }
var Q=[[2,-3],[-3,0]]; var best={e:1e9,x:null};
for(var m=0;m<4;m++){ var x=[(m>>0)&1,(m>>1)&1]; var e=qubo(x,Q); if(e<best.e)best={e:e,x:x}; }
check("optimal energy", best.e, -4);
check("optimal x=[1,1]", best.x.join(''), "11");
var __ok=true;
