// JAH demo program — ZNE linear extrapolation
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function zne(vals){ var x=[1,3,5], n=3, sx=9, sy=vals[0]+vals[1]+vals[2], sxx=35, sxy=x[0]*vals[0]+x[1]*vals[1]+x[2]*vals[2];
  var slope=(n*sxy-sx*sy)/(n*sxx-sx*sx); return (sy-slope*sx)/n; }
check("extrapolates toward true 1.0", Math.abs(zne([0.98,0.94,0.90])-1.0)<0.02, true);
check("beats the noisiest point", zne([0.98,0.94,0.90])>0.90, true);
